class_name BattleEngine
extends Node
## 核心对战规则与词条结算引擎 (BattleEngine)
## 完整实现《影之诗》×《邪恶冥刻》5列战道、三维费用（能量/献祭/骨头）、26+词条与38张卡牌精确效果结算

## 战场状态变更信号（通知 UI 刷新与播放 Tween 动画）
signal state_updated()
signal battle_log_added(msg: String)
signal floating_text_requested(side: int, lane: int, text: String, color: Color)
signal attack_anim_requested(attacker_side: int, attacker_lane: int, target_side: int, target_lane: int)
signal guard_move_requested(defender_side: int, from_lane: int, to_lane: int)
signal game_over_triggered(winner_side: int, reason: String)

## 阵营常量定义
const PLAYER: int = 0
const ENEMY: int = 1
const LANES: int = 5

## 双方主战者状态字典（索引 0 = 玩家，1 = 敌方 AI）
var leaders: Array[Dictionary] = [{}, {}]
## 双方 5 列战道随从数组：board[side][lane] -> CardInstance 或 null
var board: Array = [[null, null, null, null, null], [null, null, null, null, null]]
## 当前回合号（从 1 开始）
var turn_number: int = 1
## 当前行动阵营（0 = 玩家，1 = 敌方）
var active_side: int = PLAYER
## 对战是否已结束
var is_game_over: bool = false
var _enter_seq: int = 0

## 初始化新对战
func start_battle(player_deck_ids: Array[String], enemy_deck_ids: Array[String]) -> void:
	is_game_over = false
	turn_number = 1
	active_side = PLAYER
	board = [[null, null, null, null, null], [null, null, null, null, null]]
	leaders[PLAYER] = _create_leader_state(PLAYER, player_deck_ids)
	leaders[ENEMY] = _create_leader_state(ENEMY, enemy_deck_ids)
	_prepare_opening_hand(PLAYER)
	_prepare_opening_hand(ENEMY)
	_log("⚔️ 对战开始！双方主战者初始生命值 %d 点。" % int(CardDatabase.rules.get("hp", 20)))

func _create_leader_state(side: int, deck_ids: Array[String]) -> Dictionary:
	var deck_instances: Array[CardInstance] = []
	for cid in deck_ids:
		var inst: CardInstance = CardDatabase.create_instance(cid, side)
		if inst != null:
			deck_instances.append(inst)
	deck_instances.shuffle()
	return {
		"hp": int(CardDatabase.rules.get("hp", 20)),
		"max_hp": int(CardDatabase.rules.get("hp", 20)),
		"energy": int(CardDatabase.rules.get("energyStart", 1)),
		"max_energy": int(CardDatabase.rules.get("energyStart", 1)),
		"bones": 0,
		"deck": deck_instances,
		"hand": [] as Array[CardInstance],
		"graveyard": [] as Array[CardData], # 墓地存储被破坏的随从静态数据
		"destroyed_last_words_count": 0,    # 本局被破坏的具有谢幕曲的随从计数
		"cards_played_this_turn": 0,        # 本回合已使用卡牌张数（用于「连击」词条）
		"next_mech_discount": 0,            # 下一张机械随从能量减免（如「铜壳瓢虫」）
		"delayed_mech_draws": 0             # 下回合开始时额外抽取机械随从次数（如「飞轮信使」）
	}

## 处理起手 4 张抽牌，确保「使命必达小子」(cmwbz163tt1ma) 必定出现在未换牌前的起手手牌中
func _prepare_opening_hand(side: int) -> void:
	var st: Dictionary = leaders[side]
	var deck: Array = st["deck"]
	var hand: Array = st["hand"]
	var opening_count: int = int(CardDatabase.rules.get("openingHand", 4))
	# 检查牌库中是否有「使命必达小子」，若有则先移到牌库顶确保首抽必得
	for i in range(deck.size()):
		var inst: CardInstance = deck[i]
		if inst.data.id == "cmwbz163tt1ma" or inst.data.text.find("必定会出现在未洗牌前的起手手牌") != -1:
			deck.remove_at(i)
			deck.push_front(inst)
			break
	for i in range(opening_count):
		draw_card(side, false)

## 执行起手调度换牌（玩家可勾选任意张卡牌洗回牌库并重抽等量卡牌）
func perform_mulligan(side: int, replace_indices: Array[int]) -> void:
	if replace_indices.is_empty():
		return
	var st: Dictionary = leaders[side]
	var hand: Array = st["hand"]
	var deck: Array = st["deck"]
	replace_indices.sort()
	replace_indices.reverse()
	var returned: Array[CardInstance] = []
	for idx in replace_indices:
		if idx >= 0 and idx < hand.size():
			returned.append(hand[idx])
			hand.remove_at(idx)
	for c in returned:
		deck.append(c)
	deck.shuffle()
	for i in range(returned.size()):
		draw_card(side, false)
	_log("🔄 玩家完成了起手换牌（替换了 %d 张手牌）。" % returned.size())
	state_updated.emit()

## 开始指定阵营的回合
func begin_turn(side: int) -> void:
	if is_game_over:
		return
	active_side = side
	var st: Dictionary = leaders[side]
	st["cards_played_this_turn"] = 0
	# 第 1 回合双方均为 1 点能量；从第 2 回合开始每回合能量上限+1（最高 10）并回满
	var e_max: int = int(CardDatabase.rules.get("energyMax", 10))
	if turn_number > 1:
		st["max_energy"] = min(e_max, int(st["max_energy"]) + 1)
	st["energy"] = st["max_energy"]

	# 重置场上随从本回合「启动」状态与倒计时
	for lane in range(LANES):
		var m: CardInstance = board[side][lane]
		if m != null:
			m.activated_this_turn = false

	_log("—— 【%s的第 %d 回合】 能量 %d/%d | 骨头 %d ——" % [
		"我方" if side == PLAYER else "敌方",
		turn_number,
		int(st["energy"]),
		int(st["max_energy"]),
		int(st["bones"])
	])

	# 回合开始常规抽 1 张牌（后手第一回合额外多抽 1 张牌）
	draw_card(side)
	if side == ENEMY and turn_number == 1:
		draw_card(side)
		_log("✨ 后手第一回合额外抽取 1 张卡牌。")

	# 结算「飞轮信使」等延迟回合开始检索机械随从效果
	while int(st["delayed_mech_draws"]) > 0:
		st["delayed_mech_draws"] = int(st["delayed_mech_draws"]) - 1
		draw_specific_race(side, "机械")

	# 结算场上从左到右（敌方从右到左）的【回合开始时】效果
	var order: Array[int] = _get_lane_order(side)
	for lane in order:
		var m: CardInstance = board[side][lane]
		if m != null:
			_trigger_turn_start_effects(side, lane, m)

	state_updated.emit()

## 抽取 1 张卡牌
func draw_card(side: int, emit_ui: bool = true) -> CardInstance:
	var st: Dictionary = leaders[side]
	var deck: Array = st["deck"]
	var hand: Array = st["hand"]
	var hand_limit: int = int(CardDatabase.rules.get("handLimit", 8))
	if deck.is_empty():
		return null
	var card: CardInstance = deck.pop_front()
	if hand.size() >= hand_limit:
		_log("⚠️ %s手牌已满（%d张），抽到的【%s】爆牌消失！" % ["我方" if side == PLAYER else "敌方", hand_limit, card.data.name])
		return null
	hand.append(card)
	AudioManager.play_sfx("draw")
	if emit_ui:
		state_updated.emit()
	return card

## 从牌库检索指定种族的随从加入手牌（如「飞轮信使」谢幕曲）
func draw_specific_race(side: int, target_race: String) -> CardInstance:
	var st: Dictionary = leaders[side]
	var deck: Array = st["deck"]
	for i in range(deck.size()):
		var c: CardInstance = deck[i]
		if c.data.type == "minion" and c.data.race == target_race:
			deck.remove_at(i)
			var hand: Array = st["hand"]
			if hand.size() < int(CardDatabase.rules.get("handLimit", 8)):
				hand.append(c)
				_log("🔍 %s从牌库检索了机械随从【%s】加入手牌。" % ["我方" if side == PLAYER else "敌方", c.data.name])
			state_updated.emit()
			return c
	return null

## 将指定卡牌名称的衍生物或卡牌加入手牌（如「电子羊」「骨龙」）
func add_card_to_hand(side: int, card_name_or_id: String, count: int = 1) -> void:
	var st: Dictionary = leaders[side]
	var hand: Array = st["hand"]
	var hand_limit: int = int(CardDatabase.rules.get("handLimit", 8))
	for i in range(count):
		if hand.size() >= hand_limit:
			_log("⚠️ %s手牌已达上限 %d 张，无法继续加入【%s】。" % ["我方" if side == PLAYER else "敌方", hand_limit, card_name_or_id])
			break
		var inst: CardInstance = CardDatabase.create_instance(card_name_or_id, side)
		if inst != null:
			hand.append(inst)
	state_updated.emit()

## 检查某张手牌当前是否满足费用与献祭条件可打出
func can_play_card(side: int, card: CardInstance) -> Dictionary:
	var st: Dictionary = leaders[side]
	var need_energy: int = card.get_effective_energy(int(st["next_mech_discount"]))
	var need_bones: int = card.data.bones
	var need_sac: int = card.data.sacrifice
	var sac_cond: String = card.data.sacrifice_cond

	if int(st["energy"]) < need_energy:
		return {"ok": false, "reason": "能量不足（需要 %d 点能量）" % need_energy}
	if int(st["bones"]) < need_bones:
		return {"ok": false, "reason": "骨头不足（需要 %d 根骨头）" % need_bones}

	# 检查献祭条件
	var valid_sac_lanes: Array[int] = get_valid_sacrifice_lanes(side, sac_cond)
	if valid_sac_lanes.size() < need_sac:
		var cond_str: String = ("「%s」" % sac_cond) if sac_cond != "" else ""
		return {"ok": false, "reason": "献祭祭品不足（需要献祭 %d 个%s友方随从）" % [need_sac, cond_str]}

	# 若是随从且无需献祭，则场上必须至少有 1 个空位（若需要献祭，根据规则“位置满时依然可以使用，献祭后会腾出位置”）
	if card.data.type == "minion" and need_sac == 0:
		var has_empty: bool = false
		for l in range(LANES):
			if board[side][l] == null:
				has_empty = true
				break
		if not has_empty:
			return {"ok": false, "reason": "战场上没有空余格子"}

	return {"ok": true, "reason": ""}

## 获取场上满足指定献祭种族条件的友方随从所在列索引列表
func get_valid_sacrifice_lanes(side: int, sac_cond: String) -> Array[int]:
	var lanes: Array[int] = []
	for l in range(LANES):
		var m: CardInstance = board[side][l]
		if m != null:
			if sac_cond == "" or m.data.race == sac_cond:
				lanes.append(l)
	return lanes

## 判断某张卡牌在当前能量下是否会触发【爆能强化】
func will_trigger_enhance(side: int, card: CardInstance) -> int:
	var st: Dictionary = leaders[side]
	for kw in card.data.keywords:
		if str(kw.get("k", "")) == "爆能强化":
			var enh_val: int = int(kw.get("v", 0))
			if int(st["energy"]) >= enh_val:
				return enh_val
	return 0

## 获取卡牌的【抉择】选项列表（若无抉择则返回空数组）
func get_card_choices(card: CardInstance) -> Array:
	for kw in card.data.keywords:
		var choice_dict: Dictionary = kw.get("choice", {})
		if bool(choice_dict.get("on", false)):
			return choice_dict.get("opts", [])
	return []

## 判断卡牌从手牌打出时是否需要指定敌方/友方目标，或是选择手牌
func get_card_target_requirement(card: CardInstance, is_enhanced: bool = false) -> String:
	# 返回值：""（无需目标）、"enemy_minion"（任意敌方随从）、"enemy_minion_hp3"（生命值3以下敌方随从）、"friendly_minion"（友方随从）、"hand_card"（手牌）
	match card.data.id:
		"cmwbxdn7tcvde": # 滑板跃迁手：选择一张手牌洗入牌库并抽1张
			return "hand_card"
		"cmwc0t61ade7b": # 血偿者：选择对手战场上1个随从造成3点伤害
			return "enemy_minion"
		"cmwcah8st1lar": # 神圣法典：选择1个生命值3以下敌方随从使其消失
			return "enemy_minion_hp3"
		"cmwcalky6itcu": # 烟消云散：选择1个敌方随从使其和同名敌方随从消失
			return "enemy_minion"
		"cmwcaqbzuvvcx": # 转生苹果：选择1个友方随从赋予同名复活谢幕曲
			return "friendly_minion"
		"cmwcb1izpxl7e": # 连锁飞刃：选择1个敌方随从造成3点伤害（连击3造成5点）
			return "enemy_minion"
		"cmwcba1blx523": # 炽炎之术：爆能强化5时改为全体3伤无需指定；否则选择1个敌方随从
			return "" if is_enhanced else "enemy_minion"
	return ""

## 获取法术或入场曲的合法目标列索引列表（自动过滤具有【灵气】或【潜行】的敌方随从）
func get_valid_target_lanes(caster_side: int, req_type: String, is_spell: bool) -> Array[int]:
	var res: Array[int] = []
	var opp_side: int = 1 - caster_side
	if req_type == "enemy_minion" or req_type == "enemy_minion_hp3":
		for l in range(LANES):
			var m: CardInstance = board[opp_side][l]
			if m != null:
				# 潜行随从无法被敌方选中；法术无法指定具有【灵气】的随从
				if m.has_kw("潜行"):
					continue
				if is_spell and m.has_kw("灵气"):
					continue
				if req_type == "enemy_minion_hp3" and m.current_hp > 3:
					continue
				res.append(l)
	elif req_type == "friendly_minion":
		for l in range(LANES):
			if board[caster_side][l] != null:
				res.append(l)
	return res

## 核心出牌执行函数：完成献祭破坏、费用扣除、随从入场、入场曲/法术效果结算与立即攻击
func play_card_from_hand(
	side: int,
	card: CardInstance,
	target_lane: int = 0,
	sacrifice_lanes: Array[int] = [],
	effect_target_lane: int = -1,
	choice_index: int = 0,
	hand_target_uid: int = -1
) -> bool:
	var check: Dictionary = can_play_card(side, card)
	if not bool(check.get("ok", false)):
		return false

	var st: Dictionary = leaders[side]
	var hand: Array = st["hand"]
	var need_energy: int = card.get_effective_energy(int(st["next_mech_discount"]))
	var enh_cost: int = will_trigger_enhance(side, card)
	var is_enhanced: bool = (enh_cost > 0 and int(st["energy"]) >= enh_cost)
	if is_enhanced:
		need_energy = enh_cost

	# 1. 先执行献祭（破坏指定的友方随从，腾出格子并触发其谢幕曲与骨头+1）
	if card.data.sacrifice > 0:
		AudioManager.play_sfx("sacrifice")
		for sac_l in sacrifice_lanes:
			var sac_m: CardInstance = board[side][sac_l]
			if sac_m != null:
				_log("🩸 %s献祭了随从【%s】！" % ["我方" if side == PLAYER else "敌方", sac_m.data.name])
				destroy_minion(side, sac_l)
				if is_game_over:
					return true
		# 若目标放置列原本有非献祭随从且献祭腾出了其他空位，则自动选在空位上
		if card.data.type == "minion" and board[side][target_lane] != null:
			for l in sacrifice_lanes:
				if board[side][l] == null:
					target_lane = l
					break

	# 2. 扣除能量与骨头，移除手牌，更新本回合连击计数
	st["energy"] = int(st["energy"]) - need_energy
	st["bones"] = int(st["bones"]) - card.data.bones
	if card.data.type == "minion" and card.data.race == "机械" and int(st["next_mech_discount"]) > 0:
		st["next_mech_discount"] = 0
	hand.erase(card)
	st["cards_played_this_turn"] = int(st["cards_played_this_turn"]) + 1
	var combo_count: int = int(st["cards_played_this_turn"])

	AudioManager.play_sfx("play_card")
	_log("🃏 %s打出了【%s】（当前连击数：%d）" % ["我方" if side == PLAYER else "敌方", card.data.name, combo_count])

	# 3. 按随从或法术分支执行
	if card.data.type == "minion":
		# 若指定列仍有随从，自动寻找最左侧空列
		if board[side][target_lane] != null:
			target_lane = find_first_empty_lane(side)
		if target_lane == -1:
			return false
		_place_minion_on_board(side, card, target_lane)
		# 触发【入场曲】（仅从手牌打出时触发）
		_resolve_fanfare(side, card, target_lane, effect_target_lane, choice_index, hand_target_uid)
		# 随从放置到战场后等待点击「回合结束」时再统一按序自动发起攻击
	elif card.data.type == "spell":
		_resolve_spell(side, card, effect_target_lane, is_enhanced, combo_count)
		# 根据思维导图费用规则：「场上随从被破坏或者使用法术卡时骨头+1」
		add_bones(side, 1, "使用法术")

	state_updated.emit()
	return true

## 将随从放置或召唤到指定列，并触发【随从进场时】与赛博牧羊人光环
func _place_minion_on_board(side: int, minion: CardInstance, lane: int) -> void:
	board[side][lane] = minion
	_enter_seq += 1
	minion.lane_index = lane
	minion.enter_order = _enter_seq
	floating_text_requested.emit(side, lane, "入场", Color(0.4, 0.85, 1.0))

	# 检查己方场上的「赛博牧羊人」光环：每当机械随从进入战场时，使其获得 +1/+1
	if minion.data.race == "机械":
		for l in range(LANES):
			var ally: CardInstance = board[side][l]
			if ally != null and ally != minion and ally.data.id == "cmwbxu7u3tpyo":
				minion.add_stats(1, 1)
				_log("⚡ 【赛博牧羊人】使新入场的机械随从【%s】获得 +1/+1！" % minion.data.name)
				floating_text_requested.emit(side, lane, "+1/+1", Color(0.3, 1.0, 0.5))

	# 检查该随从自身的【随从进场时】词条（如「摇滚骷髅吉他手」进场召唤4个骷髅，不论从手牌还是瞬念召唤均触发）
	if minion.data.id == "cmwbyp6f419ju":
		_log("🎸 【摇滚骷髅吉他手】随从进场时：召唤 4 个【骷髅】到战场上！")
		summon_by_name(side, "骷髅", 4)

## 在首个空余列召唤指定卡牌名称/ID的随从（从别的途径入场，不触发入场曲，但入场后立刻攻击）
func summon_by_name(side: int, card_name_or_id: String, count: int = 1, auto_attack: bool = false) -> Array[CardInstance]:
	var summoned: Array[CardInstance] = []
	for i in range(count):
		var empty_l: int = find_first_empty_lane(side)
		if empty_l == -1:
			break
		var inst: CardInstance = CardDatabase.create_instance(card_name_or_id, side)
		if inst != null:
			_place_minion_on_board(side, inst, empty_l)
			summoned.append(inst)
			if auto_attack and not is_game_over and board[side][empty_l] == inst:
				perform_minion_combat(side, empty_l)
	return summoned

## 查找指定阵营最左侧的空列索引（若满场返回 -1）
func find_first_empty_lane(side: int) -> int:
	for l in range(LANES):
		if board[side][l] == null:
			return l
	return -1

## 结算全部随从的【入场曲】效果（精确覆盖 JSON 中的全部入场曲卡牌）
func _resolve_fanfare(
	side: int,
	card: CardInstance,
	lane: int,
	effect_target_lane: int,
	choice_index: int,
	hand_target_uid: int
) -> void:
	var st: Dictionary = leaders[side]
	var opp_side: int = 1 - side
	match card.data.id:
		"cmwas0lke5oiw": # 高性能引擎机甲：【抉择】(1) 招募_能量4 仅限机械 发动两次；(2) 亡者召还_能量4 仅限机械 发动两次
			if choice_index == 0:
				_log("⚙️ 【高性能引擎机甲】发动抉择（1）：连续两次【招募_能量4】机械随从！")
