## 结算全部法术卡效果
func _resolve_spell(side: int, card: CardInstance, target_lane: int, is_enhanced: bool, combo_count: int) -> void:
	var opp_side: int = 1 - side
	match card.data.id:
		"cmwcah8st1lar": # 神圣法典：选择1个生命值3以下敌方随从，使其消失
			if target_lane >= 0 and target_lane < LANES and board[opp_side][target_lane] != null:
				var m: CardInstance = board[opp_side][target_lane]
				if m.current_hp <= 3:
					banish_minion(opp_side, target_lane)

		"cmwcalky6itcu": # 烟消云散：选择1个敌方随从使其和与其同名的所有敌方随从消失
			if target_lane >= 0 and target_lane < LANES and board[opp_side][target_lane] != null:
				var target_name: String = board[opp_side][target_lane].data.name
				for l in range(LANES):
					if board[opp_side][l] != null and board[opp_side][l].data.name == target_name:
						banish_minion(opp_side, l)

		"cmwcaqbzuvvcx": # 转生苹果：选择1个友方随从，使其获得谢幕曲【召唤1个自己同名的随从到战场上】
			if target_lane >= 0 and target_lane < LANES and board[side][target_lane] != null:
				var ally: CardInstance = board[side][target_lane]
				ally.extra_last_words.append({
					"type": "rebirth_self",
					"card_id": ally.data.id,
					"desc": "召唤1个【%s】到战场上" % ally.data.name
				})
				_log("🍎 【转生苹果】赋予了【%s】同名复活谢幕曲！" % ally.data.name)
				floating_text_requested.emit(side, target_lane, "+转生谢幕曲", Color(0.4, 1.0, 0.5))

		"cmwcb1izpxl7e": # 连锁飞刃：【连击_3】改为造成5点伤害；选择1个敌方随从造成3点伤害
			var dmg: int = 5 if combo_count >= 3 else 3
			if target_lane >= 0 and target_lane < LANES and board[opp_side][target_lane] != null:
				_log("🗡️ 【连锁飞刃】对【%s】造成 %d 点伤害！" % [board[opp_side][target_lane].data.name, dmg])
				deal_damage_to_minion(opp_side, target_lane, dmg)

		"cmwcba1blx523": # 炽炎之术：选择1个敌方随从造成3点伤害；【爆能强化_能量5】改为对敌方随从全体造成3点伤害
			if is_enhanced:
				_log("🔥 【炽炎之术（爆能强化5）】对敌方全体随从造成 3 点伤害！")
				for l in range(LANES):
					if board[opp_side][l] != null:
						deal_damage_to_minion(opp_side, l, 3)
			elif target_lane >= 0 and target_lane < LANES and board[opp_side][target_lane] != null:
				_log("🔥 【炽炎之术】对【%s】造成 3 点伤害！" % board[opp_side][target_lane].data.name)
				deal_damage_to_minion(opp_side, target_lane, 3)

## 激活场上随从的【启动】能力（如「赛博牧羊人」消耗1点能量将2张电子羊加入手牌）
func activate_minion_ability(side: int, lane: int) -> bool:
	var m: CardInstance = board[side][lane]
	if m == null or m.activated_this_turn:
		return false
	var st: Dictionary = leaders[side]
	for kw in m.data.keywords:
		if str(kw.get("k", "")) == "启动":
			var cost_dict: Dictionary = kw.get("cost", {})
			var e_cost: int = int(cost_dict.get("energy", 0))
			var b_cost: int = int(cost_dict.get("bones", 0))
			if int(st["energy"]) < e_cost or int(st["bones"]) < b_cost:
				return false
			st["energy"] = int(st["energy"]) - e_cost
			st["bones"] = int(st["bones"]) - b_cost
			m.activated_this_turn = true
			if m.data.id == "cmwbxu7u3tpyo": # 赛博牧羊人
				_log("⚡ 发动【赛博牧羊人】启动能力：消耗 1 点能量，将 2 张【电子羊】加入手牌！")
				add_card_to_hand(side, "电子羊", 2)
			AudioManager.play_sfx("buff")
			state_updated.emit()
			return true
	return false

## 结算单个随从的战道交战（含多重攻击、两侧/三侧/全体攻击、飞行与防空、守护横移拦截、毁灭、荆棘、虹吸、位移）
func perform_minion_combat(attacker_side: int, lane: int) -> void:
	var attacker: CardInstance = board[attacker_side][lane]
	if attacker == null or is_game_over:
		return
	# 思维导图规则：「攻击为0的随从不会进行攻击，具有攻击力后开始攻击」
	if attacker.current_atk <= 0:
		return

	var multi_times: int = max(1, attacker.get_kw_val("多重攻击"))
	for hit_idx in range(multi_times):
		if is_game_over or board[attacker_side][lane] != attacker or attacker.current_atk <= 0:
			break
		_execute_single_attack_swing(attacker_side, lane, attacker)

	# 攻击结束后若随从仍在场且具有【潜行】，解除潜行；若具有【位移】，执行左右横移
	if not is_game_over and board[attacker_side][lane] == attacker:
		if attacker.has_kw("潜行"):
			attacker.remove_kw("潜行")
		if attacker.has_kw("位移"):
			_process_minion_shift(attacker_side, lane, attacker)

func _execute_single_attack_swing(attacker_side: int, lane: int, attacker: CardInstance) -> void:
	var opp_side: int = 1 - attacker_side
	# 1. 确定本次攻击的目标列集合（支持全体攻击、三侧攻击、两侧攻击、常规前方单列攻击）
	var target_lanes: Array[int] = []
	var also_fly_hit_leader: bool = false
	if attacker.has_kw("全体攻击"):
		for l in range(LANES):
			if board[opp_side][l] != null:
				target_lanes.append(l)
		var front_def: CardInstance = board[opp_side][lane]
		if attacker.has_kw("飞行") and (front_def == null or not front_def.has_kw("防空")):
			also_fly_hit_leader = true
		elif target_lanes.is_empty():
			also_fly_hit_leader = true
	elif attacker.has_kw("三侧攻击"):
		for dl in [-1, 0, 1]:
			var tl: int = lane + dl
			if tl >= 0 and tl < LANES:
				target_lanes.append(tl)
	elif attacker.has_kw("两侧攻击"):
		for dl in [-1, 1]:
			var tl: int = lane + dl
			if tl >= 0 and tl < LANES:
				target_lanes.append(tl)
	else:
		target_lanes.append(lane)

	# 2. 若是全体攻击，先对所有在场敌方随从造成伤害，若同时触发飞行直击或空场则对敌方主战者造成伤害
	if attacker.has_kw("全体攻击"):
		for tl in target_lanes:
			if is_game_over or board[attacker_side][lane] != attacker:
				break
			var def_m: CardInstance = board[opp_side][tl]
			if def_m != null:
				attack_anim_requested.emit(attacker_side, lane, opp_side, tl)
				var dealt: int = deal_damage_to_minion(opp_side, tl, attacker.current_atk, attacker)
				if def_m != null and def_m.has_kw("荆棘") and dealt > 0:
					deal_damage_to_minion(attacker_side, lane, def_m.get_kw_val("荆棘"), def_m)
		if also_fly_hit_leader and not is_game_over and board[attacker_side][lane] == attacker:
			attack_anim_requested.emit(attacker_side, lane, opp_side, -1)
			deal_damage_to_leader(opp_side, attacker.current_atk, attacker)
		return

	# 2. 依次对每个目标列执行打击
	for tl in target_lanes:
		if is_game_over or board[attacker_side][lane] != attacker:
			break
		var defender: CardInstance = board[opp_side][tl]

		# 检查【守护】自动横移机制：「在对方随从直接攻击主战者时，如果场上有空位，则该随从自动移动到该位置进行交战」
		if defender == null:
			var guard_lane: int = _find_movable_guard_lane(opp_side, tl)
			if guard_lane != -1:
				defender = board[opp_side][guard_lane]
				board[opp_side][guard_lane] = null
				board[opp_side][tl] = defender
				defender.lane_index = tl
				_log("🛡️ 敌方【%s】触发【守护】，自动横移至第 %d 列拦截攻击！" % [defender.data.name, tl + 1])
				guard_move_requested.emit(opp_side, guard_lane, tl)

		# 判断是否越过随从直接攻击主战者（【飞行】能越过没有【防空】的随从）
		var attack_leader_directly: bool = false
		if defender == null:
			attack_leader_directly = true
		elif attacker.has_kw("飞行") and not defender.has_kw("防空"):
			attack_leader_directly = true

		AudioManager.play_sfx("hit")
		if attack_leader_directly:
			attack_anim_requested.emit(attacker_side, lane, opp_side, -1)
			deal_damage_to_leader(opp_side, attacker.current_atk, attacker)
		else:
			attack_anim_requested.emit(attacker_side, lane, opp_side, tl)
			# 思维导图规则：「随从入场可以立刻攻击，攻击敌方随从不会受到敌方攻击力伤害，生命值为0时消灭」
			var dmg_dealt: int = deal_damage_to_minion(opp_side, tl, attacker.current_atk, attacker)
			# 若防守方具有【荆棘】，受到伤害时对攻击者进行反伤
			if defender != null and defender.has_kw("荆棘") and dmg_dealt > 0:
				var thorn_dmg: int = defender.get_kw_val("荆棘")
				_log("🌵 【%s】的【荆棘_%d】对【%s】造成 %d 点反伤！" % [defender.data.name, thorn_dmg, attacker.data.name, thorn_dmg])
				deal_damage_to_minion(attacker_side, lane, thorn_dmg, defender)

## 寻找可横移到空位拦截主战者直伤的【守护】随从所在列
func _find_movable_guard_lane(defender_side: int, empty_target_lane: int) -> int:
	if board[defender_side][empty_target_lane] != null:
		return -1
	var best_lane: int = -1
	var best_dist: int = 99
	for l in range(LANES):
		var m: CardInstance = board[defender_side][l]
		if m != null and m.has_kw("守护") and not m.has_kw("潜行"):
			var d: int = absi(l - empty_target_lane)
			if d < best_dist:
				best_dist = d
				best_lane = l
	return best_lane

## 处理【位移】词条：攻击结束后往右移动一格，触底或被随从阻挡则改为向左
func _process_minion_shift(side: int, lane: int, minion: CardInstance) -> void:
	var next_lane: int = lane + minion.shift_dir
	if next_lane < 0 or next_lane >= LANES or board[side][next_lane] != null:
		minion.shift_dir = -minion.shift_dir
		next_lane = lane + minion.shift_dir
	if next_lane >= 0 and next_lane < LANES and board[side][next_lane] == null:
		board[side][lane] = null
		board[side][next_lane] = minion
		minion.lane_index = next_lane
		_log("↔️ 【%s】触发【位移】移动至第 %d 列。" % [minion.data.name, next_lane + 1])

## 对指定随从造成伤害（含【屏障】抵挡、【毁灭】必杀与【虹吸】吸血）
func deal_damage_to_minion(target_side: int, lane: int, amount: int, source_minion: CardInstance = null) -> int:
	if amount <= 0:
		return 0
	var target: CardInstance = board[target_side][lane]
	if target == null:
		return 0
	# 检查【屏障】：抵挡受到的第一次伤害，至少受到1点伤害时屏障消失
	if target.has_kw("屏障"):
		target.remove_kw("屏障")
		_log("🫧 【%s】的【屏障】抵挡了本次 %d 点伤害！" % [target.data.name, amount])
		floating_text_requested.emit(target_side, lane, "屏障抵挡", Color(0.4, 0.9, 1.0))
		return 0

	target.current_hp -= amount
	floating_text_requested.emit(target_side, lane, "-%d" % amount, Color(1.0, 0.3, 0.35))

	# 检查攻击者是否具有【虹吸】
	if source_minion != null and source_minion.has_kw("虹吸"):
		heal_leader(source_minion.owner_id, amount)

	# 检查攻击者是否具有【毁灭】：「直接消灭受到该随从伤害的随从」
	if target.current_hp <= 0 or (source_minion != null and source_minion.has_kw("毁灭")):
		if source_minion != null and source_minion.has_kw("毁灭") and target.current_hp > 0:
			_log("☠️ 【%s】的【毁灭】词条直接消灭了受伤的【%s】！" % [source_minion.data.name, target.data.name])
		destroy_minion(target_side, lane)
	return amount

## 对指定主战者造成伤害
func deal_damage_to_leader(target_side: int, amount: int, source_minion: CardInstance = null) -> void:
	if amount <= 0 or is_game_over:
		return
	var st: Dictionary = leaders[target_side]
	st["hp"] = int(st["hp"]) - amount
	floating_text_requested.emit(target_side, -1, "-%d" % amount, Color(1.0, 0.25, 0.3))
	_log("💥 %s主战者受到 %d 点伤害（剩余生命：%d）" % ["我方" if target_side == PLAYER else "敌方", amount, int(st["hp"])])
	if source_minion != null and source_minion.has_kw("虹吸"):
		heal_leader(source_minion.owner_id, amount)
	if int(st["hp"]) <= 0:
		is_game_over = true
		var winner: int = 1 - target_side
		AudioManager.play_sfx("victory")
		_log("🏆 对战结束！%s获胜！" % ("我方" if winner == PLAYER else "敌方"))
		game_over_triggered.emit(winner, "%s主战者生命值归零" % ("敌方" if winner == PLAYER else "我方"))

## 为主战者恢复生命值
func heal_leader(side: int, amount: int) -> void:
	var st: Dictionary = leaders[side]
	var old_hp: int = int(st["hp"])
	st["hp"] = min(int(st["max_hp"]), old_hp + amount)
	if int(st["hp"]) > old_hp:
		floating_text_requested.emit(side, -1, "+%d" % (int(st["hp"]) - old_hp), Color(0.3, 1.0, 0.5))

## 增加骨头资源
func add_bones(side: int, amount: int, reason: String = "") -> void:
	if amount <= 0:
		return
	var st: Dictionary = leaders[side]
	st["bones"] = int(st["bones"]) + amount
	if reason != "":
		_log("🦴 %s获得 +%d 骨头（%s，当前共 %d 骨头）" % ["我方" if side == PLAYER else "敌方", amount, reason, int(st["bones"])])

## 破坏场上随从：送入墓地、骨头+1、触发【谢幕曲】与【随从离场时】
func destroy_minion(side: int, lane: int) -> void:
	var m: CardInstance = board[side][lane]
	if m == null:
		return
	board[side][lane] = null
	m.lane_index = -1
	var st: Dictionary = leaders[side]
	st["graveyard"].append(m.data)
	if m.has_any_last_words():
		st["destroyed_last_words_count"] = int(st["destroyed_last_words_count"]) + 1
	# 思维导图规则：「场上随从被破坏或者使用法术卡时骨头+1」
	add_bones(side, 1, "【%s】被破坏" % m.data.name)
	_resolve_last_words(side, lane, m)

## 消失场上随从：不进入墓地、不增加骨头、不触发谢幕曲
func banish_minion(side: int, lane: int) -> void:
	var m: CardInstance = board[side][lane]
	if m == null:
		return
	board[side][lane] = null
	m.lane_index = -1
	_log("✨ 【%s】被消失（不触发谢幕曲且不进入墓地）。" % m.data.name)
	floating_text_requested.emit(side, lane, "消失", Color(0.85, 0.7, 1.0))

## 结算全部随从的【谢幕曲】效果
func _resolve_last_words(side: int, lane: int, m: CardInstance) -> void:
	var st: Dictionary = leaders[side]
	var opp_side: int = 1 - side
	match m.data.id:
		"cmwbvfqe5en3l": # 通用载人机甲：【谢幕曲】【招募_能量2】
			_log("⚙️ 【通用载人机甲】谢幕曲：发动【招募_能量2】！")
			recruit_minion(side, 2, "")
		"cmwbvnpfgwo7a", "cmwbwne297mmg", "cmwc2zlhaxdtj": # 铁皮打手 / 发条侍从 / 齿轮学徒：将1张电子羊加入手牌
			_log("🐑 【%s】谢幕曲：将 1 张【电子羊】加入手牌。" % m.data.name)
			add_card_to_hand(side, "电子羊", 1)
		"cmwbwg3kwqfkq": # 飞轮信使：下个回合开始时，从牌库抽取一张机械随从
			st["delayed_mech_draws"] = int(st["delayed_mech_draws"]) + 1
			_log("📨 【飞轮信使】谢幕曲：预约下回合开始时抽取 1 张机械随从。")
		"cmwbyp6f419ju": # 摇滚骷髅吉他手：谢幕曲召唤四个骷髅到战场上
			_log("🎸 【摇滚骷髅吉他手】谢幕曲：召唤 4 个【骷髅】到战场上！")
			summon_by_name(side, "骷髅", 4)
		"cmwc0auyporsj": # 骸骨兽：召唤两个骷髅到战场上
			_log("💀 【骸骨兽】谢幕曲：召唤 2 个【骷髅】到战场上！")
			summon_by_name(side, "骷髅", 2)
		"cmwc0t61ade7b": # 血偿者：谢幕曲抽取1张卡牌
			_log("🩸 【血偿者】谢幕曲：抽取 1 张卡牌。")
			draw_card(side, false)
		"cmwc33vo8ohrw": # 发条龙：召唤2个电子羊到战场上
			_log("🐉 【发条龙】谢幕曲：召唤 2 个【电子羊】到战场上！")
			summon_by_name(side, "电子羊", 2)
		"cmwc3or2zf7ft": # 万齿战车：【谢幕曲】亡者召还_能量6/4/2（仅限机械）
			_log("🚜 【万齿战车】谢幕曲：依次发动能量 6 / 4 / 2 的机械【亡者召还】！")
			reanimate_minion(side, 6, "机械")
			reanimate_minion(side, 4, "机械")
			reanimate_minion(side, 2, "机械")
		"cmwc97xb64vc6", "cmwc9mbry93dx": # 尸兵 / 骸骨犬：谢幕曲骨头+2
			add_bones(side, 2, "【%s】谢幕曲" % m.data.name)
		"cmwc9ua0fd6of": # 骨龙：谢幕曲骨头+3，将1张和骨龙同名的随从加入手牌
			add_bones(side, 3, "【骨龙】谢幕曲")
			add_card_to_hand(side, "骨龙", 1)

	# 结算动态附加的额外谢幕曲（如「爆炸羊狂热者」赋予的爆破2伤、「转生苹果」赋予的同名复活）
	for extra in m.extra_last_words:
		var etype: String = str(extra.get("type", ""))
		if etype == "boom_sheep":
			_log("💥 【电子羊】触发附加谢幕曲：按入场先后顺序对敌方随从和主战者分配 2 点伤害！")
			distribute_damage(opp_side, 2, true)
		elif etype == "rebirth_self":
			var cid: String = str(extra.get("card_id", m.data.id))
			_log("🍎 触发【转生苹果】谢幕曲：重新召唤【%s】！" % m.data.name)
			summon_by_name(side, cid, 1)

## 【招募】机制：从己方牌库中随机召唤 1 张能量费用 <= max_energy 且符合 race_filter 的随从到战场上
func recruit_minion(side: int, max_energy: int, race_filter: String = "") -> CardInstance:
	var empty_l: int = find_first_empty_lane(side)
	if empty_l == -1:
		return null
	var st: Dictionary = leaders[side]
	var deck: Array = st["deck"]
	var candidates: Array[int] = []
	for i in range(deck.size()):
		var c: CardInstance = deck[i]
		if c.data.type == "minion" and c.data.energy <= max_energy:
			if race_filter == "" or c.data.race == race_filter:
				candidates.append(i)
	if candidates.is_empty():
		return null
	# 优先招募费用最高者
	candidates.sort_custom(func(ia: int, ib: int) -> bool:
		return deck[ia].data.energy > deck[ib].data.energy
	)
	var chosen_idx: int = candidates[0]
	var inst: CardInstance = deck[chosen_idx]
	deck.remove_at(chosen_idx)
	_log("📣 【招募】从牌库召唤了【%s】到第 %d 列！" % [inst.data.name, empty_l + 1])
	_place_minion_on_board(side, inst, empty_l)
	# 招募/亡者召还入场的随从同样在回合结束时统一发起攻击
	return inst

## 【亡者召还】机制：从己方墓地中召唤 1 张能量费用 <= max_energy（优先最高费）且符合 race_filter 的随从到战场上
func reanimate_minion(side: int, max_energy: int, race_filter: String = "") -> CardInstance:
	var empty_l: int = find_first_empty_lane(side)
	if empty_l == -1:
		return null
	var st: Dictionary = leaders[side]
	var grave: Array = st["graveyard"]
	var best_data: CardData = null
	for cd in grave:
		if cd.type == "minion" and cd.energy <= max_energy:
			if race_filter == "" or cd.race == race_filter:
				if best_data == null or cd.energy > best_data.energy:
					best_data = cd
	if best_data == null:
		return null
	var inst: CardInstance = CardDatabase.create_instance(best_data.id, side)
	_log("⚰️ 【亡者召还_%d】从墓地复活了【%s】到第 %d 列！" % [max_energy, inst.data.name, empty_l + 1])
	_place_minion_on_board(side, inst, empty_l)
	# 招募/亡者召还入场的随从同样在回合结束时统一发起攻击
	return inst

## 结束当前阵营回合（严格遵循思维导图结算顺序：瞬念召唤先于回合结束时触发；己方从左到右，敌方从右到左）
func end_turn(side: int) -> void:
	if is_game_over or active_side != side:
		return

	# 0. 点击回合结束后，当前回合方场上随从按顺序（我方从左到右 0..4，敌方从右到左 4..0）自动攻击
	var atk_order: Array[int] = _get_lane_order(side)
	for lane in atk_order:
		if is_game_over:
			return
		var attacker: CardInstance = board[side][lane]
		if attacker != null:
			perform_minion_combat(side, lane)

	# 1. 结算【瞬念召唤】（思维导图规则：「瞬念召唤先于回合结束时触发」）
	_process_invocation_effects(side)

	# 2. 再按顺序（己方从左到右 0..4，敌方从右到左 4..0）结算场上随从的【回合结束时】效果
	var order: Array[int] = _get_lane_order(side)
	for lane in order:
		var m: CardInstance = board[side][lane]
		if m != null:
			_trigger_turn_end_effects(side, lane, m)

	# 3. 切换到对手回合
	if not is_game_over:
		if side == PLAYER:
			begin_turn(ENEMY)
			_run_enemy_ai_turn()
		else:
			turn_number += 1
			begin_turn(PLAYER)

## 检查并触发牌库中的【瞬念召唤】（如「魔导机兵少女」「摇滚骷髅吉他手」）
func _process_invocation_effects(side: int) -> void:
	var st: Dictionary = leaders[side]
	var deck: Array = st["deck"]

	# 检查 1：魔导机兵少女 (cmwbx0mq8qz7f) —— 如果己方场上拥有 5 个机械随从，破坏全部随从，从牌库召唤并获得全体攻击
	var mech_board_count: int = 0
	for l in range(LANES):
		if board[side][l] != null and board[side][l].data.race == "机械":
			mech_board_count += 1
	if mech_board_count == 5:
		for i in range(deck.size()):
			var c: CardInstance = deck[i]
			if c.data.id == "cmwbx0mq8qz7f":
				deck.remove_at(i)
				_log("🌟 满足 5 机械条件！触发【魔导机兵少女】瞬念召唤：破坏己方全部随从，降临战场并对敌方全体随从造成4点伤害！")
				for l in range(LANES):
					if board[side][l] != null:
						destroy_minion(side, l)
				var empty_l: int = find_first_empty_lane(side)
				if empty_l != -1:
					c.grant_kw("全体攻击", 1)
					_place_minion_on_board(side, c, empty_l)
					if not is_game_over and board[side][empty_l] == c:
						perform_minion_combat(side, empty_l)
				break

	# 检查 2：摇滚骷髅吉他手 (cmwbyp6f419ju) —— 若本次对战中自己被破坏的具有谢幕曲的随从 >= 10 个，召唤到战场上
	if int(st["destroyed_last_words_count"]) >= 10 and find_first_empty_lane(side) != -1:
		for i in range(deck.size()):
			var c: CardInstance = deck[i]
			if c.data.id == "cmwbyp6f419ju":
				deck.remove_at(i)
				var empty_l: int = find_first_empty_lane(side)
				_log("🎸 已破坏 %d 个谢幕曲随从！触发【摇滚骷髅吉他手】瞬念召唤！" % int(st["destroyed_last_words_count"]))
				_place_minion_on_board(side, c, empty_l)
				if not is_game_over and board[side][empty_l] == c:
					perform_minion_combat(side, empty_l)
				break

func _trigger_turn_start_effects(_side: int, _lane: int, _m: CardInstance) -> void:
	pass

func _trigger_turn_end_effects(side: int, lane: int, m: CardInstance) -> void:
	if m.data.id == "cmwc96kid9cw4": # 掘墓者：【回合结束时】骨头+1
		add_bones(side, 1, "【掘墓者】回合结束")
		floating_text_requested.emit(side, lane, "骨头+1", Color(0.95, 0.9, 0.75))

func _get_lane_order(side: int) -> Array[int]:
	if side == PLAYER:
		return [0, 1, 2, 3, 4]
	return [4, 3, 2, 1, 0]

func _count_mech_in_hand(side: int) -> int:
	var cnt: int = 0
	for c in leaders[side]["hand"]:
		if c.data.race == "机械":
			cnt += 1
	return cnt

## 智能 AI 对手出牌与决策逻辑
func _run_enemy_ai_turn() -> void:
	if is_game_over:
		return
	var st: Dictionary = leaders[ENEMY]
	var acted: bool = true
	while acted and not is_game_over:
		acted = false
		var hand: Array = st["hand"]
		for c in hand.duplicate():
			var check: Dictionary = can_play_card(ENEMY, c)
			if not bool(check.get("ok", false)):
				continue
			var is_enh: bool = (will_trigger_enhance(ENEMY, c) > 0)
			var req: String = get_card_target_requirement(c, is_enh)
			var eff_target: int = -1
			if req == "enemy_minion" or req == "enemy_minion_hp3":
				var valid_t: Array[int] = get_valid_target_lanes(ENEMY, req, c.data.type == "spell")
				if valid_t.is_empty():
					if c.data.type == "spell":
						continue
				else:
					eff_target = valid_t[0]
			elif req == "friendly_minion":
				var valid_f: Array[int] = get_valid_target_lanes(ENEMY, req, true)
				if valid_f.is_empty():
					continue
				eff_target = valid_f[0]

			# 选择献祭祭品（优先选择攻击力最低的随从如松鼠、电子羊、骷髅）
			var sac_lanes: Array[int] = []
			if c.data.sacrifice > 0:
				var valid_s: Array[int] = get_valid_sacrifice_lanes(ENEMY, c.data.sacrifice_cond)
				valid_s.sort_custom(func(la: int, lb: int) -> bool:
					return board[ENEMY][la].current_atk < board[ENEMY][lb].current_atk
				)
				for i in range(c.data.sacrifice):
					sac_lanes.append(valid_s[i])

			# 选择放置列（优先对位阻挡我方高攻随从或空列）
			var place_lane: int = find_first_empty_lane(ENEMY)
			if place_lane == -1 and not sac_lanes.is_empty():
				place_lane = sac_lanes[0]
			for l in range(LANES):
				if board[ENEMY][l] == null and board[PLAYER][l] != null:
					place_lane = l
					break

			var choice_idx: int = 0
			if c.data.id == "cmwc3gozg0rat" and _count_mech_in_hand(ENEMY) >= 3:
				choice_idx = 1
			if play_card_from_hand(ENEMY, c, max(0, place_lane), sac_lanes, eff_target, choice_idx):
				acted = true
				break

	# 尝试激活场上随从的【启动】能力
	for l in range(LANES):
		if board[ENEMY][l] != null:
			activate_minion_ability(ENEMY, l)

	# 敌方场攻结算：回合内已在各随从入场时立即攻击，此处对在场老随从执行本回合例行战道攻击
	for l in [4, 3, 2, 1, 0]:
		if is_game_over:
			break
		var m: CardInstance = board[ENEMY][l]
		if m != null:
			perform_minion_combat(ENEMY, l)

	if not is_game_over:
		end_turn(ENEMY)

func _log(msg: String) -> void:
	battle_log_added.emit(msg)

## 按随从最先进入战场的顺序（enter_order 升序）依次分配伤害；随从死亡后剩余伤害继续转移给下一个随从，若 include_leader 为真则溢出伤害打在主战者身上
func distribute_damage(target_side: int, total_dmg: int, include_leader: bool = true, source_minion: CardInstance = null) -> void:
	var rem: int = total_dmg
	while rem > 0 and not is_game_over:
		var alive_lanes: Array[int] = []
		for l in range(LANES):
			if board[target_side][l] != null:
				alive_lanes.append(l)
		if alive_lanes.is_empty():
			if include_leader:
				deal_damage_to_leader(target_side, rem, source_minion)
			break
		alive_lanes.sort_custom(func(la: int, lb: int) -> bool:
			return board[target_side][la].enter_order < board[target_side][lb].enter_order
		)
		var first_lane: int = alive_lanes[0]
		var m: CardInstance = board[target_side][first_lane]
		if m.has_kw("屏障"):
			deal_damage_to_minion(target_side, first_lane, 1, source_minion)
			rem -= 1
		else:
			var needed: int = max(1, m.current_hp)
			var dmg_now: int = min(rem, needed)
			deal_damage_to_minion(target_side, first_lane, dmg_now, source_minion)
			rem -= dmg_now

CardView.gd:
class_name CardView
extends Control
## 影之诗风格华丽卡面组件 (CardView)
## 采用 Godot _draw() 程序化矢量绘制卡框、稀有度宝石、三维费用角标（能量/献祭/骨头）、种族主题插画、词条徽章与攻防数值
## 支持鼠标悬停放大发光、可打出绿色流光呼吸、选中献祭红框等丰富交互反馈

signal card_clicked(card_view: CardView)
signal card_right_clicked(card_view: CardView)
signal card_hovered(card_view: CardView, is_hovering: bool)

## 关联的静态卡牌模板数据
var card_data: CardData
## 关联的运行时实例（若在手牌或战场上则非空）
var card_instance: CardInstance
## 展示模式："hand"（手牌）、"board"（战场随从）、"gallery"（构筑图鉴）
var display_mode: String = "gallery"
## 是否处于可打出高亮状态
var is_playable: bool = false
## 是否被当前选中（出牌选中或献祭选中）
var is_selected: bool = false
## 是否为待选祭品高亮
var is_sacrifice_candidate: bool = false
## 构筑模式下显示的已投入数量角标（0 表示不显示）
var deck_count_badge: int = 0

var _is_hovered: bool = false
var _hover_tween: Tween

func _init() -> void:
	custom_minimum_size = Vector2(150, 210)
	mouse_filter = Control.MOUSE_FILTER_STOP

func setup_from_data(data: CardData, mode: String = "gallery") -> void:
	card_data = data
	card_instance = null
	display_mode = mode
	_update_size_for_mode()
	queue_redraw()

func setup_from_instance(inst: CardInstance, mode: String = "hand") -> void:
	card_instance = inst
	card_data = inst.data if inst != null else null
	display_mode = mode
	_update_size_for_mode()
	queue_redraw()

func _update_size_for_mode() -> void:
	match display_mode:
		"board":
			custom_minimum_size = Vector2(136, 168)
		"hand":
			custom_minimum_size = Vector2(142, 198)
		_:
			custom_minimum_size = Vector2(156, 218)
	size = custom_minimum_size
	pivot_offset = size * 0.5

func _ready() -> void:
	mouse_entered.connect(_on_mouse_entered)
	mouse_exited.connect(_on_mouse_exited)

func _gui_input(event: InputEvent) -> void:
	if event is InputEventMouseButton and event.pressed:
		if event.button_index == MOUSE_BUTTON_LEFT:
			card_clicked.emit(self)
		elif event.button_index == MOUSE_BUTTON_RIGHT:
			card_right_clicked.emit(self)

func _on_mouse_entered() -> void:
	_is_hovered = true
	z_index = 20
	if _hover_tween and _hover_tween.is_running():
		_hover_tween.kill()
	_hover_tween = create_tween().set_ease(Tween.EASE_OUT).set_trans(Tween.TRANS_BACK)
	var target_scale := Vector2(1.14, 1.14) if display_mode == "hand" else Vector2(1.06, 1.06)
	_hover_tween.tween_property(self, "scale", target_scale, 0.14)
	card_hovered.emit(self, true)
	queue_redraw()

func _on_mouse_exited() -> void:
	_is_hovered = false
	z_index = 0
	if _hover_tween and _hover_tween.is_running():
		_hover_tween.kill()
	_hover_tween = create_tween().set_ease(Tween.EASE_OUT).set_trans(Tween.TRANS_QUAD)
	_hover_tween.tween_property(self, "scale", Vector2.ONE, 0.12)
	card_hovered.emit(self, false)
	queue_redraw()

func _draw() -> void:
	if card_data == null:
		return
	var rect := Rect2(Vector2.ZERO, size)
	var font: Font = ThemeDB.fallback_font
	var rarity_col: Color = card_data.get_rarity_color()

	# 1. 绘制外发光（可打出/选中/悬停/献祭候选）
	if is_selected:
		_draw_rounded_box(rect.grow(5.0), Color(1.0, 0.84, 0.25, 0.85), Color.TRANSPARENT, 0.0)
	elif is_sacrifice_candidate:
		_draw_rounded_box(rect.grow(4.0), Color(0.95, 0.22, 0.28, 0.85), Color.TRANSPARENT, 0.0)
	elif is_playable:
		_draw_rounded_box(rect.grow(3.5), Color(0.22, 0.95, 0.55, 0.72), Color.TRANSPARENT, 0.0)
	elif _is_hovered:
		_draw_rounded_box(rect.grow(3.0), Color(0.45, 0.75, 1.0, 0.55), Color.TRANSPARENT, 0.0)

	# 2. 绘制卡牌底板与金属边框
	var bg_col := Color(0.10, 0.12, 0.18)
	if card_data.race == "机械":
		bg_col = Color(0.09, 0.15, 0.24)
	elif card_data.race == "亡灵":
		bg_col = Color(0.15, 0.10, 0.20)
	elif card_data.type == "spell":
		bg_col = Color(0.18, 0.11, 0.16)
	_draw_rounded_box(rect, bg_col, rarity_col, 2.5)

	# 3. 绘制卡面中心程序化主题插画区
	var art_h: float = size.y * (0.46 if display_mode != "board" else 0.54)
	var art_rect := Rect2(Vector2(8, 28), Vector2(size.x - 16, art_h))
	_draw_procedural_art(art_rect)

	# 4. 绘制顶部名称横幅
	var title_rect := Rect2(Vector2(6, 5), Vector2(size.x - 12, 22))
	draw_rect(title_rect, Color(0.05, 0.06, 0.10, 0.88), true)
	draw_string(font, Vector2(30, 21), card_data.name, HORIZONTAL_ALIGNMENT_LEFT, size.x - 36, 13, Color(0.98, 0.96, 0.90))

	# 5. 绘制左上角三维费用徽章（能量 / 献祭 / 骨头）
	var eff_energy: int = card_instance.get_effective_energy() if card_instance != null else card_data.energy
	var badge_y: float = 16.0
	if eff_energy > 0 or (card_data.sacrifice == 0 and card_data.bones == 0):
		draw_circle(Vector2(16, badge_y), 12.0, Color(0.12, 0.56, 0.98))
		draw_arc(Vector2(16, badge_y), 12.0, 0, TAU, 24, Color(0.75, 0.92, 1.0), 2.0)
		draw_string(font, Vector2(6, badge_y + 5), str(eff_energy), HORIZONTAL_ALIGNMENT_CENTER, 20, 14, Color.WHITE)
		badge_y += 24.0
	if card_data.sacrifice > 0:
		draw_circle(Vector2(16, badge_y), 11.5, Color(0.78, 0.12, 0.18))
		draw_arc(Vector2(16, badge_y), 11.5, 0, TAU, 24, Color(1.0, 0.65, 0.65), 1.8)
		draw_string(font, Vector2(4, badge_y + 4), "祭" + str(card_data.sacrifice), HORIZONTAL_ALIGNMENT_CENTER, 24, 11, Color(1.0, 0.92, 0.92))
		badge_y += 23.0
	if card_data.bones > 0:
		draw_circle(Vector2(16, badge_y), 11.5, Color(0.72, 0.66, 0.52))
		draw_arc(Vector2(16, badge_y), 11.5, 0, TAU, 24, Color(0.96, 0.94, 0.86), 1.8)
		draw_string(font, Vector2(4, badge_y + 4), "骨" + str(card_data.bones), HORIZONTAL_ALIGNMENT_CENTER, 24, 11, Color(0.12, 0.10, 0.08))

	# 6. 绘制种族与类型飘带
	var type_y: float = art_rect.end.y + 14.0
	draw_rect(Rect2(Vector2(8, art_rect.end.y + 1), Vector2(size.x - 16, 16)), Color(0.06, 0.08, 0.13, 0.92), true)
	draw_string(font, Vector2(10, type_y), card_data.get_type_cn() + " · " + card_data.rarity, HORIZONTAL_ALIGNMENT_CENTER, size.x - 20, 11, rarity_col)

	# 7. 绘制效果描述或战场词条徽章
	if display_mode == "board" and card_instance != null:
		var badges: Array[String] = card_instance.get_badge_list()
		var bx: float = 10.0
		var by: float = type_y + 16.0
		for b_txt in badges:
			var bw: float = min(size.x - 20.0, float(b_txt.length() * 11 + 10))
			if bx + bw > size.x - 8.0:
				bx = 10.0
				by += 18.0
			draw_rect(Rect2(Vector2(bx, by - 12), Vector2(bw, 16)), Color(0.18, 0.26, 0.42, 0.95), true)
			draw_string(font, Vector2(bx + 4, by), b_txt, HORIZONTAL_ALIGNMENT_LEFT, bw - 4, 10, Color(0.95, 0.92, 0.65))
			bx += bw + 4.0
	else:
		var desc_rect := Rect2(Vector2(8, type_y + 4), Vector2(size.x - 16, size.y - type_y - 30))
		draw_rect(desc_rect, Color(0.05, 0.06, 0.09, 0.85), true)
		var desc_str: String = card_data.get_display_text()
		if card_instance != null and not card_instance.extra_last_words.is_empty():
			desc_str += "\n【附加谢幕曲】"
		_draw_wrapped_text(font, desc_str, Rect2(desc_rect.position + Vector2(4, 12), desc_rect.size - Vector2(8, 6)), 10, Color(0.88, 0.90, 0.95))

	# 8. 如果是随从，绘制左下角攻击力与右下角生命值（含守护盾牌外框）
	if card_data.type == "minion":
		var show_atk: int = card_instance.current_atk if card_instance != null else card_data.atk
		var show_hp: int = card_instance.current_hp if card_instance != null else card_data.hp
		var has_guard: bool = card_instance.has_kw("守护") if card_instance != null else card_data.has_keyword("守护")
		if has_guard:
			draw_rect(rect.grow(-2.0), Color(0.95, 0.82, 0.32, 0.9), false, 3.0)

		# 左下角攻击力剑标
		var atk_pos := Vector2(18, size.y - 16)
		draw_circle(atk_pos, 14.0, Color(0.16, 0.44, 0.88))
		draw_arc(atk_pos, 14.0, 0, TAU, 24, Color(0.65, 0.86, 1.0), 2.0)
		draw_string(font, atk_pos + Vector2(-12, 5), str(show_atk), HORIZONTAL_ALIGNMENT_CENTER, 24, 14, Color.WHITE)

		# 右下角生命值血滴标
		var hp_pos := Vector2(size.x - 18, size.y - 16)
		var hp_col := Color(0.82, 0.18, 0.24)
		draw_circle(hp_pos, 14.0, hp_col)
		draw_arc(hp_pos, 14.0, 0, TAU, 24, Color(1.0, 0.72, 0.75), 2.0)
		var txt_col := Color(0.4, 1.0, 0.5) if (card_instance != null and show_hp > card_data.hp) else Color.WHITE
		draw_string(font, hp_pos + Vector2(-12, 5), str(show_hp), HORIZONTAL_ALIGNMENT_CENTER, 24, 14, txt_col)

	# 9. 构筑模式下若已投入卡组，右上角显示 "×N" 徽章
	if deck_count_badge > 0:
		var badge_rect := Rect2(Vector2(size.x - 36, 4), Vector2(32, 20))
		draw_rect(badge_rect, Color(0.92, 0.65, 0.12), true)
		draw_string(font, Vector2(size.x - 34, 18), "x%d" % deck_count_badge, HORIZONTAL_ALIGNMENT_CENTER, 28, 12, Color(0.08, 0.08, 0.1))

## 根据卡牌种族与属性绘制独特的程序化几何奇幻插画
func _draw_procedural_art(r: Rect2) -> void:
	var c1 := Color(0.14, 0.24, 0.38)
	var c2 := Color(0.28, 0.65, 0.95)
	if card_data.race == "机械":
		c1 = Color(0.08, 0.22, 0.34)
		c2 = Color(0.15, 0.85, 0.96)
	elif card_data.race == "亡灵":
		c1 = Color(0.16, 0.08, 0.24)
		c2 = Color(0.68, 0.32, 0.92)
	elif card_data.type == "spell":
		c1 = Color(0.26, 0.10, 0.18)
		c2 = Color(0.98, 0.45, 0.25)
	draw_rect(r, c1, true)
	var center: Vector2 = r.get_center()
	var radius: float = min(r.size.x, r.size.y) * 0.34
	# 依据卡牌 ID 哈希生成稳定的几何纹章
	var seed_val: int = absi(card_data.id.hash())
	var points_cnt: int = 3 + (seed_val % 5)
	draw_circle(center, radius * 1.05, Color(c2.r, c2.g, c2.b, 0.22))
	draw_arc(center, radius * 0.88, 0, TAU, 32, c2, 2.0)
	var poly: PackedVector2Array = []
	for i in range(points_cnt):
		var ang: float = float(i) * TAU / float(points_cnt) - PI * 0.5
		poly.append(center + Vector2(cos(ang), sin(ang)) * radius * 0.72)
	if poly.size() >= 3:
		draw_colored_polygon(poly, Color(c2.r, c2.g, c2.b, 0.45))
	draw_rect(r, card_data.get_rarity_color(), false, 1.2)

func _draw_rounded_box(r: Rect2, fill: Color, border: Color, border_w: float) -> void:
	draw_rect(r, fill, true)
	if border_w > 0.0:
		draw_rect(r, border, false, border_w)

func _draw_wrapped_text(font: Font, txt: String, area: Rect2, fsize: int, col: Color) -> void:
	var lines: PackedStringArray = txt.split("\n")
	var y: float = area.position.y
	var max_chars_per_line: int = max(8, int(area.size.x / (float(fsize) * 0.95)))
	for raw_line in lines:
		var pos: int = 0
		while pos < raw_line.length():
			if y > area.end.y:
				return
			var sub: String = raw_line.substr(pos, max_chars_per_line)
			draw_string(font, Vector2(area.position.x, y), sub, HORIZONTAL_ALIGNMENT_LEFT, area.size.x, fsize, col)
			y += float(fsize) + 3.0
			pos += max_chars_per_line

