class_name DeckBuilderView
extends Control
## 卡组构筑界面控制器 (DeckBuilderView)
## 支持按种族/费用/关键词筛选全部 38 张卡牌、查看卡牌完整大图详情、左键添加/右键移除卡组卡牌、
## 切换三套预设卡组、一键智能补满 40 张、导入卡牌设计器 v1.9 JSON 数据并持久化保存

signal back_to_menu_requested()
signal start_battle_requested()

var _filter_race: String = "全部"
var _include_tokens: bool = false
var _search_keyword: String = ""

var _card_grid: GridContainer
var _deck_list_vbox: VBoxContainer
var _deck_selector: OptionButton
var _status_label: Label
var _detail_label: RichTextLabel
var _file_dialog: FileDialog
var _import_text_edit: TextEdit

func _ready() -> void:
	_build_ui()
	_refresh_all()

func _build_ui() -> void:
	# 背景底色
	var bg := ColorRect.new()
	bg.color = Color(0.06, 0.08, 0.13)
	bg.set_anchors_preset(Control.PRESET_FULL_RECT)
	add_child(bg)

	var root_vbox := VBoxContainer.new()
	root_vbox.set_anchors_preset(Control.PRESET_FULL_RECT)
	root_vbox.add_theme_constant_override("separation", 10)
	add_child(root_vbox)

	# 顶部导航与筛选工具栏
	var top_bar := HBoxContainer.new()
	top_bar.custom_minimum_size = Vector2(0, 52)
	top_bar.add_theme_constant_override("separation", 12)
	root_vbox.add_child(top_bar)

	var btn_back := Button.new()
	btn_back.text = "◀ 返回主菜单"
	btn_back.custom_minimum_size = Vector2(130, 40)
	btn_back.pressed.connect(func() -> void:
		AudioManager.play_sfx("click")
		DeckManager.save_decks()
		back_to_menu_requested.emit()
	)
	top_bar.add_child(btn_back)

	var title_lbl := Label.new()
	title_lbl.text = "🛠️ 卡组构筑工坊（左键加入卡组 / 右键移出卡组）"
	title_lbl.add_theme_font_size_override("font_size", 18)
	top_bar.add_child(title_lbl)

	# 种族筛选按钮组
	for r_name in ["全部", "机械", "亡灵", "法术"]:
		var fb := Button.new()
		fb.text = r_name
		fb.custom_minimum_size = Vector2(68, 36)
		fb.pressed.connect(func() -> void:
			AudioManager.play_sfx("click")
			_filter_race = r_name
			_refresh_card_pool()
		)
		top_bar.add_child(fb)

	var token_chk := CheckButton.new()
	token_chk.text = "显示衍生物(电子羊/骷髅)"
	token_chk.toggled.connect(func(on: bool) -> void:
		_include_tokens = on
		_refresh_card_pool()
	)
	top_bar.add_child(token_chk)

	var search_box := LineEdit.new()
	search_box.placeholder_text = "搜索卡名/词条(如 谢幕曲/招募)..."
	search_box.custom_minimum_size = Vector2(210, 36)
	search_box.text_changed.connect(func(new_txt: String) -> void:
		_search_keyword = new_txt.strip_edges()
		_refresh_card_pool()
	)
	top_bar.add_child(search_box)

	var btn_import := Button.new()
	btn_import.text = "📥 导入设计器JSON"
	btn_import.pressed.connect(_show_import_dialog)
	top_bar.add_child(btn_import)

	# 主体左右分栏：左侧卡牌收藏网格 + 中部选中卡牌详情 + 右侧当前卡组列表
	var body_hbox := HBoxContainer.new()
	body_hbox.size_flags_vertical = Control.SIZE_EXPAND_FILL
	body_hbox.add_theme_constant_override("separation", 14)
	root_vbox.add_child(body_hbox)

	# 左侧卡牌池滚动区
	var pool_scroll := ScrollContainer.new()
	pool_scroll.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	pool_scroll.size_flags_stretch_ratio = 2.7
	body_hbox.add_child(pool_scroll)

	_card_grid = GridContainer.new()
	_card_grid.columns = 5
	_card_grid.add_theme_constant_override("h_separation", 14)
	_card_grid.add_theme_constant_override("v_separation", 14)
	pool_scroll.add_child(_card_grid)

	# 右侧卡组管理面板
	var right_panel := PanelContainer.new()
	right_panel.custom_minimum_size = Vector2(440, 0)
	body_hbox.add_child(right_panel)

	var right_vbox := VBoxContainer.new()
	right_vbox.add_theme_constant_override("separation", 8)
	right_panel.add_child(right_vbox)

	# 预设卡组切换下拉框
	var deck_top := HBoxContainer.new()
	right_vbox.add_child(deck_top)
	_deck_selector = OptionButton.new()
	_deck_selector.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	for i in range(DeckManager.decks.size()):
		_deck_selector.add_item(str(DeckManager.decks[i].get("name", "卡组 %d" % (i + 1))), i)
	_deck_selector.selected = DeckManager.current_deck_index
	_deck_selector.item_selected.connect(func(idx: int) -> void:
		DeckManager.current_deck_index = idx
		_refresh_all()
	)
	deck_top.add_child(_deck_selector)

	var btn_auto := Button.new()
	btn_auto.text = "✨ 自动补满40张"
	btn_auto.pressed.connect(func() -> void:
		AudioManager.play_sfx("buff")
		DeckManager.auto_complete_deck(DeckManager.get_current_deck())
		DeckManager.save_decks()
		_refresh_all()
	)
	deck_top.add_child(btn_auto)

	var btn_clear := Button.new()
	btn_clear.text = "🗑️ 清空"
	btn_clear.pressed.connect(func() -> void:
		AudioManager.play_sfx("click")
		DeckManager.get_current_deck()["cards"] = {}
		_refresh_all()
	)
	deck_top.add_child(btn_clear)

	_status_label = Label.new()
	_status_label.add_theme_font_size_override("font_size", 15)
	right_vbox.add_child(_status_label)

	var deck_scroll := ScrollContainer.new()
	deck_scroll.size_flags_vertical = Control.SIZE_EXPAND_FILL
	right_vbox.add_child(deck_scroll)

	_deck_list_vbox = VBoxContainer.new()
	_deck_list_vbox.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	_deck_list_vbox.add_theme_constant_override("separation", 4)
	deck_scroll.add_child(_deck_list_vbox)

	# 选中卡牌完整规则详情展示框
	_detail_label = RichTextLabel.new()
	_detail_label.bbcode_enabled = true
	_detail_label.custom_minimum_size = Vector2(0, 150)
	_detail_label.text = "[b]💡 悬停或点击左侧任意卡牌查看完整词条与设计师备注[/b]"
	right_vbox.add_child(_detail_label)

	var btn_battle := Button.new()
	btn_battle.text = "⚔️ 使用当前卡组开始对战"
	btn_battle.custom_minimum_size = Vector2(0, 46)
	btn_battle.pressed.connect(func() -> void:
		var check: Dictionary = DeckManager.validate_deck(DeckManager.get_current_deck())
		if not bool(check.get("valid", false)):
			DeckManager.auto_complete_deck(DeckManager.get_current_deck())
		DeckManager.save_decks()
		AudioManager.play_sfx("turn")
		start_battle_requested.emit()
	)
	right_vbox.add_child(btn_battle)

	# 初始化本地文件选择弹窗（支持直接选择电脑中的 .json 卡牌设计器导出文件）
	_file_dialog = FileDialog.new()
	_file_dialog.file_mode = FileDialog.FILE_MODE_OPEN_FILE
	_file_dialog.access = FileDialog.ACCESS_FILESYSTEM
	_file_dialog.filters = PackedStringArray(["*.json ; 卡牌设计器 JSON 文件"])
	_file_dialog.title = "选择电脑中的「卡牌构筑对战 · 卡牌设计器」JSON 文件"
	_file_dialog.min_size = Vector2(720, 480)
	_file_dialog.file_selected.connect(_on_file_selected)
	add_child(_file_dialog)

func _refresh_all() -> void:
	_refresh_card_pool()
	_refresh_deck_list()

func _refresh_card_pool() -> void:
	for child in _card_grid.get_children():
		child.queue_free()
	var cur_deck: Dictionary = DeckManager.get_current_deck()
	var cards_map: Dictionary = cur_deck.get("cards", {})
	for c in CardDatabase.all_cards:
		if not _include_tokens and c.is_token:
			continue
		if _filter_race == "机械" and c.race != "机械":
			continue
		if _filter_race == "亡灵" and c.race != "亡灵":
			continue
		if _filter_race == "法术" and c.type != "spell":
			continue
		if _search_keyword != "":
			var hay: String = c.name + c.race + c.get_display_text() + c.notes
			if hay.find(_search_keyword) == -1:
				continue

		var cv := CardView.new()
		cv.setup_from_data(c, "gallery")
		cv.deck_count_badge = int(cards_map.get(c.id, 0))
		cv.card_clicked.connect(func(_v: CardView) -> void:
			_add_card_to_current_deck(c)
		)
		cv.card_right_clicked.connect(func(_v: CardView) -> void:
			_remove_card_from_current_deck(c.id)
		)
		cv.card_hovered.connect(func(_v: CardView, hovering: bool) -> void:
			if hovering:
				_show_card_detail(c)
		)
		_card_grid.add_child(cv)

func _refresh_deck_list() -> void:
	for child in _deck_list_vbox.get_children():
		child.queue_free()
	var cur_deck: Dictionary = DeckManager.get_current_deck()
	var cards_map: Dictionary = cur_deck.get("cards", {})
	var check: Dictionary = DeckManager.validate_deck(cur_deck)
	_status_label.text = str(check.get("reason", ""))
	_status_label.modulate = Color(0.35, 1.0, 0.55) if bool(check.get("valid", false)) else Color(1.0, 0.72, 0.35)

	var sorted_ids: Array = cards_map.keys()
	sorted_ids.sort_custom(func(a: String, b: String) -> bool:
		var ca: CardData = CardDatabase.get_card(a)
		var cb: CardData = CardDatabase.get_card(b)
		if ca == null or cb == null:
			return a < b
		if ca.energy != cb.energy:
			return ca.energy < cb.energy
		return ca.bones < cb.bones
	)

	for cid in sorted_ids:
		var cnt: int = int(cards_map[cid])
		if cnt <= 0:
			continue
		var c: CardData = CardDatabase.get_card(cid)
		if c == null:
			continue
		var row := HBoxContainer.new()
		var cost_lbl := Label.new()
		var cost_parts: PackedStringArray = []
		if c.energy > 0 or (c.sacrifice == 0 and c.bones == 0):
			cost_parts.append("⚡%d" % c.energy)
		if c.sacrifice > 0:
			cost_parts.append("🩸%d" % c.sacrifice)
		if c.bones > 0:
			cost_parts.append("🦴%d" % c.bones)
		cost_lbl.text = "[" + "/".join(cost_parts) + "]"
		cost_lbl.custom_minimum_size = Vector2(90, 28)
		row.add_child(cost_lbl)

		var name_btn := Button.new()
		name_btn.text = "%s  × %d" % [c.name, cnt]
		name_btn.size_flags_horizontal = Control.SIZE_EXPAND_FILL
		name_btn.alignment = HORIZONTAL_ALIGNMENT_LEFT
		name_btn.pressed.connect(func() -> void:
			_show_card_detail(c)
			_remove_card_from_current_deck(c.id)
		)
		row.add_child(name_btn)
		_deck_list_vbox.add_child(row)

func _add_card_to_current_deck(c: CardData) -> void:
	if c.is_token:
		_show_card_detail(c)
		return
	var cur_deck: Dictionary = DeckManager.get_current_deck()
	var cards_map: Dictionary = cur_deck.get("cards", {})
	var max_copies: int = int(CardDatabase.rules.get("copiesPerCard", 3))
	var max_total: int = int(CardDatabase.rules.get("deckSize", 40))
	var cur_cnt: int = int(cards_map.get(c.id, 0))
	if cur_cnt >= max_copies or DeckManager.get_deck_total_count(cur_deck) >= max_total:
		AudioManager.play_sfx("hit")
		return
	cards_map[c.id] = cur_cnt + 1
	AudioManager.play_sfx("click")
	DeckManager.save_decks()
	_refresh_all()

func _remove_card_from_current_deck(cid: String) -> void:
	var cur_deck: Dictionary = DeckManager.get_current_deck()
	var cards_map: Dictionary = cur_deck.get("cards", {})
	if not cards_map.has(cid):
		return
	var cur_cnt: int = int(cards_map[cid]) - 1
	if cur_cnt <= 0:
		cards_map.erase(cid)
	else:
		cards_map[cid] = cur_cnt
	AudioManager.play_sfx("click")
	DeckManager.save_decks()
	_refresh_all()

func _show_card_detail(c: CardData) -> void:
	var cost_info: String = "能量:%d | 献祭:%d%s | 骨头:%d" % [
		c.energy,
		c.sacrifice,
		("(%s)" % c.sacrifice_cond if c.sacrifice_cond != "" else ""),
		c.bones
	]
	var stat_info: String = ("攻击:%d / 生命:%d" % [c.atk, c.hp]) if c.type == "minion" else "法术卡"
	var note_str: String = ("\n[color=#99b8ff]设计备注：%s[/color]" % c.notes) if c.notes != "" else ""
	_detail_label.text = "[b]【%s】[/b] (%s · %s)\n%s  |  %s\n[color=#ffe89e]%s[/color]%s" % [
		c.name,
		c.get_type_cn(),
		c.rarity,
		cost_info,
		stat_info,
		c.get_display_text(),
		note_str
	]

func _show_import_dialog() -> void:
	_file_dialog.popup_centered()

func _on_file_selected(file_path: String) -> void:
	if not FileAccess.file_exists(file_path):
		return
	var rf := FileAccess.open(file_path, FileAccess.READ)
	if rf == null:
		return
	var raw: String = rf.get_as_text()
	rf.close()
	if CardDatabase.parse_json_string(raw, true):
		var wf := FileAccess.open("user://custom_cards.json", FileAccess.WRITE)
		if wf != null:
			wf.store_string(raw)
			wf.close()
		AudioManager.play_sfx("victory")
		_refresh_all()
